insert into te_passages (id, title, body, source, grade_level, difficulty, org_id) values
  ('b0000001-0000-0000-0000-000000000001', 'The Trap of Sunk Costs', 'A movie has been boring for thirty minutes, yet many viewers stay until the credits roll. Economists call this a sunk cost trap.', 'thinking-english seed', 10, 'mid', null),
  ('b0000002-0000-0000-0000-000000000002', 'Plastic That Disappears Into Water', 'Plastic bottles eventually break, but they do not vanish. They split into pieces too small to see, and those pieces enter the food chain.', 'thinking-english seed', 11, 'mid', null),
  ('b0000003-0000-0000-0000-000000000003', 'Why We Notice What We Already Believe', 'Two people watch the same news and walk away with opposite conclusions. The reason has less to do with the news than with the watchers.', 'thinking-english seed', 11, 'mid', null),
  ('b0000004-0000-0000-0000-000000000004', 'How an Algorithm Builds a Bubble', 'Each time a user clicks on a video about one topic, the recommendation system narrows the offerings. Soon, the feed shows only one side of the world.', 'thinking-english seed', 11, 'mid', null),
  ('b0000005-0000-0000-0000-000000000005', 'The Silk Road Was More Than Silk', 'When people think of the ancient Silk Road, they picture caravans loaded with cloth. The cloth was almost the smallest part of what traveled.', 'thinking-english seed', 10, 'mid', null),
  ('b0000006-0000-0000-0000-000000000006', 'When Painters Discovered Depth', 'Medieval paintings often look flat to a modern eye. The world was painted as the mind imagined it, not as the eye saw it.', 'thinking-english seed', 11, 'mid', null),
  ('b0000007-0000-0000-0000-000000000007', 'A Sugar Pill That Heals', 'In careful trials, patients given pills with no active medicine still report real improvement. The effect is not a trick. It is the brain at work.', 'thinking-english seed', 11, 'mid', null),
  ('b0000008-0000-0000-0000-000000000008', 'When Villages Become Cities', 'For most of history, more than nine out of ten people lived in the countryside. In the past century, the balance flipped, with consequences few foresaw.', 'thinking-english seed', 10, 'mid', null),
  ('b0000009-0000-0000-0000-000000000009', 'The Old Argument About Free Choice', 'When you decide what to eat, does the decision really belong to you, or was it set in motion by a thousand earlier causes?', 'thinking-english seed', 11, 'mid', null),
  ('b000000a-0000-0000-0000-00000000000a', 'High Context, Low Context', 'In some cultures, the meaning of a sentence is mostly in the words themselves. In others, far more meaning hides in the situation around the words.', 'thinking-english seed', 11, 'mid', null),
  ('b000000b-0000-0000-0000-00000000000b', 'The Body Clock Inside You', 'Even in a windowless room with no clock, the body follows a daily rhythm of about twenty-four hours. The rhythm is built into the cells themselves.', 'thinking-english seed', 10, 'mid', null),
  ('b000000c-0000-0000-0000-00000000000c', 'What You Give Up by Choosing', 'Every choice has a hidden cost. Picking one option means letting go of every other option you could have picked instead.', 'thinking-english seed', 10, 'mid', null),
  ('b000000d-0000-0000-0000-00000000000d', 'The Most Wanted Thing Online', 'Apps compete for users, but the deeper competition is for something less obvious. The real product is the time and focus of the audience.', 'thinking-english seed', 11, 'mid', null),
  ('b000000e-0000-0000-0000-00000000000e', 'Animals That Pretend', 'Some harmless insects wear the same colors as dangerous ones. Other animals copy the shape of leaves or stones. Across nature, fake identity is a strategy.', 'thinking-english seed', 10, 'mid', null),
  ('b000000f-0000-0000-0000-00000000000f', 'Why New Cities Mix Everything', 'Old city plans separated homes, shops, and offices into different zones. New plans put them on the same street, and the change has surprising effects.', 'thinking-english seed', 11, 'mid', null),
  ('b0000010-0000-0000-0000-000000000010', 'A Sad Song in Every Language', 'When a researcher plays unfamiliar music to people from different countries, most can still tell which songs are sad. Some patterns cross every border.', 'thinking-english seed', 10, 'mid', null),
  ('b0000011-0000-0000-0000-000000000011', 'How a Shared Language Spread', 'Across busy ports of the past, traders from a dozen homelands had to do business with one another. A simplified shared language emerged out of need.', 'thinking-english seed', 11, 'mid', null),
  ('b0000012-0000-0000-0000-000000000012', 'Why Tomorrow Feels Less Real', 'Most people choose a small reward today over a larger one next month, even when the math clearly favors waiting. The mind treats future selves like strangers.', 'thinking-english seed', 11, 'mid', null),
  ('b0000013-0000-0000-0000-000000000013', 'Two Prisoners and a Choice', 'Imagine two suspects, kept in separate rooms, each offered a deal. Together they could win, but each has a private reason to betray the other.', 'thinking-english seed', 11, 'mid', null),
  ('b0000014-0000-0000-0000-000000000014', 'The Missing Mass of the Universe', 'Astronomers add up everything they can see and find that the math does not balance. Most of the universe seems to be made of matter no telescope can detect.', 'thinking-english seed', 11, 'mid', null);

-- ===== 단락 ===========================================================
insert into te_paragraphs (passage_id, ord, body) values
  ('b0000001-0000-0000-0000-000000000001', 0, 'The viewer thinks, I already paid for the ticket, so I should stay. But the money is gone whether they stay or leave. The only honest question is whether the next hour will be enjoyable.'),
  ('b0000001-0000-0000-0000-000000000001', 1, 'The same logic ruins many decisions. People keep reading a boring book because they finished half of it. They stay in a job because they spent years learning it.'),
  ('b0000001-0000-0000-0000-000000000001', 2, 'A good decision looks forward, not backward. What is already spent cannot come back, so it should not steer the next step.'),

  ('b0000002-0000-0000-0000-000000000002', 0, 'When a plastic bottle reaches the ocean, the sun and salt slowly tear it apart. The pieces become microscopic, but the material itself remains plastic.'),
  ('b0000002-0000-0000-0000-000000000002', 1, 'Small fish swallow the tiny particles. Larger fish eat the small fish. By the time the chain reaches our plates, the plastic has come back to us.'),
  ('b0000002-0000-0000-0000-000000000002', 2, 'The problem cannot be cleaned up after the fact. The only real cure is producing less of the material that does not truly go away.'),

  ('b0000003-0000-0000-0000-000000000003', 0, 'The mind does not record everything it sees with equal weight. It pays extra attention to facts that match what we already think, and it quietly skips the rest.'),
  ('b0000003-0000-0000-0000-000000000003', 1, 'This bias is hard to feel from inside. The skipped facts never leave a mark, so it seems like the world simply lined up with our view.'),
  ('b0000003-0000-0000-0000-000000000003', 2, 'The remedy is uncomfortable. We have to seek out the very evidence we would rather avoid, and read it carefully before we judge it.'),

  ('b0000004-0000-0000-0000-000000000004', 0, 'An algorithm has one job: predict what will keep your eyes on the screen. It learns from every pause, every replay, every scroll.'),
  ('b0000004-0000-0000-0000-000000000004', 1, 'Over weeks, the predictions become accurate, but also narrow. The system shows what you already like, not what might broaden your view.'),
  ('b0000004-0000-0000-0000-000000000004', 2, 'Breaking out of this bubble requires effort the system will not provide. You have to deliberately seek out voices the feed never serves you.'),

  ('b0000005-0000-0000-0000-000000000005', 0, 'Along the Silk Road, traders carried more than goods. They carried ideas, religions, recipes, instruments, and diseases.'),
  ('b0000005-0000-0000-0000-000000000005', 1, 'A piece of writing in one language was copied into another in a market town, then traveled east or west with the next caravan. Whole faiths spread along the same routes that carried spices.'),
  ('b0000005-0000-0000-0000-000000000005', 2, 'The lesson is that trade routes are never only about trade. Whenever people meet to exchange things, they end up exchanging much more than they intended.'),

  ('b0000006-0000-0000-0000-000000000006', 0, 'In medieval art, distant people are sometimes drawn larger than nearby ones, because they were more important to the story. The size showed meaning, not distance.'),
  ('b0000006-0000-0000-0000-000000000006', 1, 'In the Renaissance, painters worked out the geometry of perspective. Lines that ran away from the viewer met at a single hidden point, and suddenly paintings opened like windows.'),
  ('b0000006-0000-0000-0000-000000000006', 2, 'It was not that earlier artists could not see depth. They had chosen a different goal. When the goal changed, the technique followed.'),

  ('b0000007-0000-0000-0000-000000000007', 0, 'A patient who believes a pill will help often reports less pain even when the pill contains nothing active. This is called the placebo effect.'),
  ('b0000007-0000-0000-0000-000000000007', 1, 'Brain scans show that expectation alone can trigger the release of natural painkillers. The healing is not imaginary; the body really shifts.'),
  ('b0000007-0000-0000-0000-000000000007', 2, 'This does not mean medicine is unnecessary. It means that hope, trust, and ritual are quietly working alongside the chemistry.'),

  ('b0000008-0000-0000-0000-000000000008', 0, 'In 1900, only one in seven people lived in a city. Today more than half of the world is urban, and the share keeps climbing.'),
  ('b0000008-0000-0000-0000-000000000008', 1, 'Cities make jobs and ideas easier to find. They also stretch transit, raise rents, and concentrate pollution. The benefits and the costs grow together.'),
  ('b0000008-0000-0000-0000-000000000008', 2, 'The future of urban life is not whether to grow but how. Cities that plan ahead live differently from cities that grow only because people arrive.'),

  ('b0000009-0000-0000-0000-000000000009', 0, 'Every choice we make rests on a long history. Genes, culture, hunger, sleep, and the mood of the moment all push the decision in directions we barely notice.'),
  ('b0000009-0000-0000-0000-000000000009', 1, 'Some philosophers argue this leaves no room for a free choice at all. Others say freedom is not freedom from causes but the ability to respond to reasons.'),
  ('b0000009-0000-0000-0000-000000000009', 2, 'Whichever side you take, the question itself sharpens the way you act. A decision made with awareness still feels different from one made on autopilot.'),

  ('b000000a-0000-0000-0000-00000000000a', 0, 'In a low-context culture, a clear, direct sentence is polite. People rely on the words to carry the meaning, and asking too many indirect questions feels evasive.'),
  ('b000000a-0000-0000-0000-00000000000a', 1, 'In a high-context culture, a direct sentence can feel rude. Listeners read the relationship, the tone, and the silence as carefully as the words themselves.'),
  ('b000000a-0000-0000-0000-00000000000a', 2, 'Misunderstandings often come from style, not from disagreement. A speaker from one tradition may be saying yes while the listener from another tradition hears no.'),

  ('b000000b-0000-0000-0000-00000000000b', 0, 'In experiments, volunteers have lived for weeks in caves with no sunlight and no clocks. Their bodies still cycled close to a twenty-four-hour rhythm.'),
  ('b000000b-0000-0000-0000-00000000000b', 1, 'This internal clock controls more than sleep. It sets the timing of hormone release, body temperature, and even the strength of the immune system at different hours of the day.'),
  ('b000000b-0000-0000-0000-00000000000b', 2, 'Working long night shifts forces the body to fight its own clock. Over years, the fight has measurable health costs.'),

  ('b000000c-0000-0000-0000-00000000000c', 0, 'When you pick chocolate ice cream, you are not only choosing chocolate. You are also choosing not to have any other flavor in the case.'),
  ('b000000c-0000-0000-0000-00000000000c', 1, 'Economists call the value of the option you gave up the opportunity cost. It is invisible, so most people forget to count it.'),
  ('b000000c-0000-0000-0000-00000000000c', 2, 'Big decisions become clearer once we ask what we are giving up, not only what we are getting. The choice that looked obvious sometimes loses to a quieter alternative.'),

  ('b000000d-0000-0000-0000-00000000000d', 0, 'When a service is free, the user is usually not the customer. Advertisers are the customers, and the user is the product whose attention is sold.'),
  ('b000000d-0000-0000-0000-00000000000d', 1, 'Attention is a limited resource. There are only so many hours in a day, and many apps fight for the same ones.'),
  ('b000000d-0000-0000-0000-00000000000d', 2, 'Once we see attention as a currency, the choice of how to spend it becomes more serious. Endless scrolling is not free time; it is paid time, paid in something we cannot earn back.'),

  ('b000000e-0000-0000-0000-00000000000e', 0, 'A harmless hoverfly wears the same yellow and black stripes as a stinging wasp. Birds that have been stung once avoid both insects.'),
  ('b000000e-0000-0000-0000-00000000000e', 1, 'Other animals hide rather than mimic. A stick insect looks like a twig, a leaf insect like a torn leaf. Stillness completes the disguise.'),
  ('b000000e-0000-0000-0000-00000000000e', 2, 'Mimicry shows that evolution does not need to invent new tools. Borrowing the appearance of something dangerous, or of nothing at all, often works just as well.'),

  ('b000000f-0000-0000-0000-00000000000f', 0, 'A traditional city zoned for cars made every trip long. Going to the store, to school, or to work required a separate journey.'),
  ('b000000f-0000-0000-0000-00000000000f', 1, 'A mixed-use street puts shops on the ground floor, offices above, and apartments on top. Daily life can happen within a few minutes of walking.'),
  ('b000000f-0000-0000-0000-00000000000f', 2, 'The change does more than save time. Streets fill with people throughout the day, which makes them safer and livelier in ways that empty zoned areas never become.'),

  ('b0000010-0000-0000-0000-000000000010', 0, 'When sad music is played slowly with low notes, listeners around the world tend to call it sad, even without being told what the lyrics mean.'),
  ('b0000010-0000-0000-0000-000000000010', 1, 'Researchers suspect that some musical patterns echo the sound of the human body. Slow tempos resemble a sleeping heartbeat; low pitches resemble a quiet voice.'),
  ('b0000010-0000-0000-0000-000000000010', 2, 'Music varies enormously across cultures, but a small core seems to be shared. The body, it turns out, is a universal listener.'),

  ('b0000011-0000-0000-0000-000000000011', 0, 'In a port where Greek, Arabic, Persian, and Italian traders all met, no one wanted to learn three new languages just to sell goods. A simpler shared form emerged from the mix.'),
  ('b0000011-0000-0000-0000-000000000011', 1, 'A trade language usually has a small vocabulary and simple grammar. It is built for usefulness, not for poetry.'),
  ('b0000011-0000-0000-0000-000000000011', 2, 'Sometimes such a language fades when the trade route closes. Sometimes, surprisingly, it grows roots and becomes a native language for the next generation.'),

  ('b0000012-0000-0000-0000-000000000012', 0, 'Offer a child a candy now or two candies in an hour. Many will choose the one candy. The future second candy feels less real than the candy in front of them.'),
  ('b0000012-0000-0000-0000-000000000012', 1, 'Adults make the same mistake on bigger scales. They skip exercise that pays off next year for comfort tonight. They borrow tomorrow''s money for today''s purchase.'),
  ('b0000012-0000-0000-0000-000000000012', 2, 'Knowing about this bias does not erase it, but it changes the conversation we have with ourselves. The future self becomes a person worth keeping a promise to.'),

  ('b0000013-0000-0000-0000-000000000013', 0, 'If both prisoners stay silent, both get a light sentence. If both betray each other, both get a heavy one. If one stays silent and one betrays, the betrayer walks free and the silent one suffers most.'),
  ('b0000013-0000-0000-0000-000000000013', 1, 'Looking at the choice alone, betraying always pays. But if both follow that logic, both lose. Cooperation would have been better for everyone.'),
  ('b0000013-0000-0000-0000-000000000013', 2, 'This puzzle appears far outside prisons. Countries deciding on pollution, neighbors deciding on noise, students deciding on group projects all face a version of the same trap.'),

  ('b0000014-0000-0000-0000-000000000014', 0, 'When astronomers measure the speed of galaxies, the stars spin too fast for the visible matter alone to hold them together. Something invisible must add the extra pull.'),
  ('b0000014-0000-0000-0000-000000000014', 1, 'The unseen material is called dark matter. It does not give off light, and it ignores almost everything except gravity.'),
  ('b0000014-0000-0000-0000-000000000014', 2, 'About eighty-five percent of all matter in the universe is thought to be dark. Most of what holds the cosmos together is hidden in plain sight.');

-- ===== 문제 (지문당 3개 평균: 주제 1 + 빈칸 1 + 어휘 1) ==================
insert into te_questions (passage_id, topic, prompt, choices, correct_answer, explanation, difficulty, grade_level, org_id) values
  ('b0000001-0000-0000-0000-000000000001', 'main_idea', 'What is the main idea?',
   '[{"key":"1","text":"Once you have paid for something, you should always finish it."},{"key":"2","text":"Past spending should not control future decisions."},{"key":"3","text":"Movies must always be enjoyable."},{"key":"4","text":"Reading half of a book guarantees finishing it."}]',
   '2', '본문 결론 그대로: 이미 쓴 것이 다음 결정을 좌우하면 안 된다.', 'mid', 10, null),
  ('b0000001-0000-0000-0000-000000000001', 'blank', 'Fill in the blank: A good decision looks ____, not backward.',
   '[{"key":"1","text":"sideways"},{"key":"2","text":"forward"},{"key":"3","text":"down"},{"key":"4","text":"away"}]',
   '2', 'looks forward, not backward.', 'mid', 10, null),
  ('b0000001-0000-0000-0000-000000000001', 'vocabulary', 'In the passage, "steer" most nearly means:',
   '[{"key":"1","text":"to control the direction of"},{"key":"2","text":"to delete"},{"key":"3","text":"to enlarge"},{"key":"4","text":"to ignore"}]',
   '1', 'steer the next step → 다음 단계를 끌고가다.', 'mid', 10, null),

  ('b0000002-0000-0000-0000-000000000002', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Plastic in the ocean eventually disappears."},{"key":"2","text":"Plastic breaks into tiny pieces and returns to humans through food."},{"key":"3","text":"Cleaning the ocean is easy."},{"key":"4","text":"Microscopic plastic is harmless."}]',
   '2', '전체 단락 흐름: 분해되지 않고 작아져 먹이사슬로 회귀.', 'mid', 11, null),
  ('b0000002-0000-0000-0000-000000000002', 'blank', 'Fill in the blank: The only real cure is producing ____ of the material.',
   '[{"key":"1","text":"more"},{"key":"2","text":"less"},{"key":"3","text":"thicker"},{"key":"4","text":"colored"}]',
   '2', 'producing less of the material.', 'mid', 11, null),
  ('b0000002-0000-0000-0000-000000000002', 'vocabulary', 'In the passage, "swallow" most nearly means:',
   '[{"key":"1","text":"to spit out"},{"key":"2","text":"to take into the body through the mouth"},{"key":"3","text":"to bite off"},{"key":"4","text":"to throw away"}]',
   '2', '본문: small fish swallow the tiny particles.', 'mid', 11, null),

  ('b0000003-0000-0000-0000-000000000003', 'main_idea', 'What is the main idea?',
   '[{"key":"1","text":"The mind treats all evidence equally."},{"key":"2","text":"We notice evidence that confirms what we already believe and skip the rest."},{"key":"3","text":"News is always biased."},{"key":"4","text":"Avoiding evidence is the best way to learn."}]',
   '2', '본문 핵심: 확증편향. 마지막 단락이 해결책까지 제시.', 'mid', 11, null),
  ('b0000003-0000-0000-0000-000000000003', 'blank', 'Fill in the blank: The remedy is uncomfortable. We have to seek out the very ____ we would rather avoid.',
   '[{"key":"1","text":"friends"},{"key":"2","text":"snacks"},{"key":"3","text":"evidence"},{"key":"4","text":"weather"}]',
   '3', 'the very evidence we would rather avoid.', 'mid', 11, null),
  ('b0000003-0000-0000-0000-000000000003', 'vocabulary', 'In the passage, "bias" most nearly means:',
   '[{"key":"1","text":"a tendency to lean in one direction"},{"key":"2","text":"a kind of weather"},{"key":"3","text":"a quick answer"},{"key":"4","text":"a fair view"}]',
   '1', 'bias → 편향.', 'mid', 11, null),

  ('b0000004-0000-0000-0000-000000000004', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Algorithms always broaden your view."},{"key":"2","text":"Recommendation systems narrow what you see, and breaking out takes deliberate effort."},{"key":"3","text":"Users should never click on videos."},{"key":"4","text":"Algorithms are randomly designed."}]',
   '2', '본문 결론: 의도적으로 다른 목소리를 찾아야 탈출 가능.', 'mid', 11, null),
  ('b0000004-0000-0000-0000-000000000004', 'blank', 'Fill in the blank: An algorithm has one job: predict what will keep your ____ on the screen.',
   '[{"key":"1","text":"voice"},{"key":"2","text":"eyes"},{"key":"3","text":"fingers"},{"key":"4","text":"books"}]',
   '2', 'keep your eyes on the screen.', 'mid', 11, null),
  ('b0000004-0000-0000-0000-000000000004', 'vocabulary', 'In the passage, "deliberately" most nearly means:',
   '[{"key":"1","text":"by accident"},{"key":"2","text":"on purpose"},{"key":"3","text":"silently"},{"key":"4","text":"sleepily"}]',
   '2', 'deliberately seek out → 의도적으로.', 'mid', 11, null),

  ('b0000005-0000-0000-0000-000000000005', 'main_idea', 'What is the main idea?',
   '[{"key":"1","text":"The Silk Road only carried silk."},{"key":"2","text":"Trade routes also transported ideas, religions, and even diseases."},{"key":"3","text":"Caravans avoided market towns."},{"key":"4","text":"Spices were the only valuable cargo."}]',
   '2', '본문 흐름: 옷감은 일부, 더 많은 것이 같이 이동.', 'mid', 10, null),
  ('b0000005-0000-0000-0000-000000000005', 'blank', 'Fill in the blank: Whenever people meet to exchange things, they end up exchanging ____ more than they intended.',
   '[{"key":"1","text":"much"},{"key":"2","text":"silver"},{"key":"3","text":"little"},{"key":"4","text":"nothing"}]',
   '1', 'much more than they intended.', 'mid', 10, null),
  ('b0000005-0000-0000-0000-000000000005', 'vocabulary', 'In the passage, "caravan" most nearly means:',
   '[{"key":"1","text":"a single horse"},{"key":"2","text":"a group of traders traveling together"},{"key":"3","text":"a small village"},{"key":"4","text":"a port city"}]',
   '2', 'caravan → 대상, 무리.', 'mid', 10, null),

  ('b0000006-0000-0000-0000-000000000006', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Medieval artists could not see depth."},{"key":"2","text":"Artistic technique follows the artist''s changing goals."},{"key":"3","text":"Renaissance painters invented painting itself."},{"key":"4","text":"Importance should always be shown by size."}]',
   '2', '본문 결론: 목표가 바뀌면 기법이 따라온다.', 'mid', 11, null),
  ('b0000006-0000-0000-0000-000000000006', 'blank', 'Fill in the blank: Lines that ran away from the viewer met at a single hidden ____.',
   '[{"key":"1","text":"painter"},{"key":"2","text":"point"},{"key":"3","text":"river"},{"key":"4","text":"door"}]',
   '2', 'single hidden point.', 'mid', 11, null),
  ('b0000006-0000-0000-0000-000000000006', 'vocabulary', 'In the passage, "open like windows" most nearly means:',
   '[{"key":"1","text":"break apart"},{"key":"2","text":"feel like real views into space"},{"key":"3","text":"hide what is behind them"},{"key":"4","text":"become smaller"}]',
   '2', '비유: 그림이 창처럼 공간으로 열린다 → 실제 공간감.', 'mid', 11, null),

  ('b0000007-0000-0000-0000-000000000007', 'main_idea', 'What is the main idea?',
   '[{"key":"1","text":"The placebo effect proves medicine is unnecessary."},{"key":"2","text":"Belief alone can cause real bodily changes that ease pain."},{"key":"3","text":"Patients always imagine improvements."},{"key":"4","text":"Pills with no medicine cannot affect the body."}]',
   '2', '본문 핵심: 신뢰·기대만으로 진짜 신체 반응 발생.', 'mid', 11, null),
  ('b0000007-0000-0000-0000-000000000007', 'blank', 'Fill in the blank: Hope, trust, and ____ are quietly working alongside the chemistry.',
   '[{"key":"1","text":"ritual"},{"key":"2","text":"silence"},{"key":"3","text":"darkness"},{"key":"4","text":"hunger"}]',
   '1', 'hope, trust, and ritual.', 'mid', 11, null),
  ('b0000007-0000-0000-0000-000000000007', 'vocabulary', 'In the passage, "trigger" most nearly means:',
   '[{"key":"1","text":"to set off or cause"},{"key":"2","text":"to stop suddenly"},{"key":"3","text":"to forget"},{"key":"4","text":"to invent"}]',
   '1', 'trigger the release → 방출을 촉발하다.', 'mid', 11, null),

  ('b0000008-0000-0000-0000-000000000008', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Cities are always bad."},{"key":"2","text":"The future of urban life is shaped by how cities plan their growth."},{"key":"3","text":"More people should live in the countryside."},{"key":"4","text":"Cities never make pollution worse."}]',
   '2', '마지막 단락의 직접 진술: 계획이 있는 도시와 없는 도시는 다르다.', 'mid', 10, null),
  ('b0000008-0000-0000-0000-000000000008', 'blank', 'Fill in the blank: In 1900, only one in ____ people lived in a city.',
   '[{"key":"1","text":"three"},{"key":"2","text":"five"},{"key":"3","text":"seven"},{"key":"4","text":"ten"}]',
   '3', 'one in seven.', 'mid', 10, null),
  ('b0000008-0000-0000-0000-000000000008', 'vocabulary', 'In the passage, "concentrate" most nearly means:',
   '[{"key":"1","text":"to spread thinly"},{"key":"2","text":"to bring together in one place"},{"key":"3","text":"to study quietly"},{"key":"4","text":"to remove"}]',
   '2', 'concentrate pollution → 한 곳에 모으다.', 'mid', 10, null),

  ('b0000009-0000-0000-0000-000000000009', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Free will does not exist."},{"key":"2","text":"Whether or not free will exists, awareness changes how we act."},{"key":"3","text":"Genes alone decide everything."},{"key":"4","text":"Philosophers always agree."}]',
   '2', '본문 마지막 문장의 핵심: 의식이 행동의 질을 바꾼다.', 'mid', 11, null),
  ('b0000009-0000-0000-0000-000000000009', 'blank', 'Fill in the blank: A decision made with awareness still feels different from one made on ____.',
   '[{"key":"1","text":"autopilot"},{"key":"2","text":"vacation"},{"key":"3","text":"silence"},{"key":"4","text":"music"}]',
   '1', 'made on autopilot.', 'mid', 11, null),
  ('b0000009-0000-0000-0000-000000000009', 'vocabulary', 'In the passage, "sharpen" most nearly means:',
   '[{"key":"1","text":"to make duller"},{"key":"2","text":"to make clearer or more focused"},{"key":"3","text":"to cut into small pieces"},{"key":"4","text":"to copy"}]',
   '2', 'sharpens the way you act → 행동을 더 명료하게.', 'mid', 11, null),

  ('b000000a-0000-0000-0000-00000000000a', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Direct sentences are universally polite."},{"key":"2","text":"Misunderstandings often come from cultural communication style, not from disagreement."},{"key":"3","text":"Silence is always rude."},{"key":"4","text":"All cultures rely on words equally."}]',
   '2', '마지막 단락의 직접 진술.', 'mid', 11, null),
  ('b000000a-0000-0000-0000-00000000000a', 'blank', 'Fill in the blank: In a high-context culture, listeners read the relationship, the tone, and the ____.',
   '[{"key":"1","text":"silence"},{"key":"2","text":"weather"},{"key":"3","text":"map"},{"key":"4","text":"book"}]',
   '1', 'relationship, the tone, and the silence.', 'mid', 11, null),
  ('b000000a-0000-0000-0000-00000000000a', 'vocabulary', 'In the passage, "evasive" most nearly means:',
   '[{"key":"1","text":"clear and open"},{"key":"2","text":"trying to avoid giving a direct answer"},{"key":"3","text":"easily understood"},{"key":"4","text":"newly written"}]',
   '2', 'asking too many indirect questions feels evasive → 회피하다.', 'mid', 11, null),

  ('b000000b-0000-0000-0000-00000000000b', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Without sunlight, the body has no rhythm."},{"key":"2","text":"The body keeps an internal twenty-four-hour rhythm that controls many systems."},{"key":"3","text":"Night shifts have no effect on health."},{"key":"4","text":"Clocks shape biology only when visible."}]',
   '2', '도입과 전개 모두 같은 결론으로 연결.', 'mid', 10, null),
  ('b000000b-0000-0000-0000-00000000000b', 'blank', 'Fill in the blank: This internal clock controls the timing of hormone release, body temperature, and even the strength of the ____ system.',
   '[{"key":"1","text":"immune"},{"key":"2","text":"highway"},{"key":"3","text":"musical"},{"key":"4","text":"banking"}]',
   '1', 'immune system.', 'mid', 10, null),
  ('b000000b-0000-0000-0000-00000000000b', 'vocabulary', 'In the passage, "cycle" most nearly means:',
   '[{"key":"1","text":"to ride a bike"},{"key":"2","text":"to repeat in regular patterns"},{"key":"3","text":"to stop completely"},{"key":"4","text":"to switch off"}]',
   '2', 'cycled close to a twenty-four-hour rhythm.', 'mid', 10, null),

  ('b000000c-0000-0000-0000-00000000000c', 'main_idea', 'What is the main idea?',
   '[{"key":"1","text":"Every choice has a hidden cost — the value of what we gave up."},{"key":"2","text":"Choosing one flavor is never a real decision."},{"key":"3","text":"Big decisions have no costs."},{"key":"4","text":"Economists rarely talk about ice cream."}]',
   '1', '본문 전체가 기회비용 설명.', 'mid', 10, null),
  ('b000000c-0000-0000-0000-00000000000c', 'blank', 'Fill in the blank: Economists call the value of the option you gave up the ____ cost.',
   '[{"key":"1","text":"sunk"},{"key":"2","text":"opportunity"},{"key":"3","text":"hidden"},{"key":"4","text":"loud"}]',
   '2', 'opportunity cost.', 'mid', 10, null),
  ('b000000c-0000-0000-0000-00000000000c', 'vocabulary', 'In the passage, "invisible" most nearly means:',
   '[{"key":"1","text":"not able to be seen"},{"key":"2","text":"very loud"},{"key":"3","text":"easy to find"},{"key":"4","text":"colorful"}]',
   '1', 'It is invisible → 눈에 보이지 않는다.', 'mid', 10, null),

  ('b000000d-0000-0000-0000-00000000000d', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Free services are truly free."},{"key":"2","text":"On many platforms, the user''s attention is the actual product being sold."},{"key":"3","text":"Apps do not compete with each other."},{"key":"4","text":"Endless scrolling is a great use of time."}]',
   '2', '본문 전체의 핵심: 어텐션 이코노미.', 'mid', 11, null),
  ('b000000d-0000-0000-0000-00000000000d', 'blank', 'Fill in the blank: When a service is free, the user is usually not the customer. Advertisers are the customers, and the user is the ____.',
   '[{"key":"1","text":"owner"},{"key":"2","text":"product"},{"key":"3","text":"server"},{"key":"4","text":"engineer"}]',
   '2', 'the user is the product.', 'mid', 11, null),
  ('b000000d-0000-0000-0000-00000000000d', 'vocabulary', 'In the passage, "currency" most nearly means:',
   '[{"key":"1","text":"something used as money or to trade"},{"key":"2","text":"a small river"},{"key":"3","text":"a daily habit"},{"key":"4","text":"a kind of light"}]',
   '1', 'attention as a currency → 화폐로서.', 'mid', 11, null),

  ('b000000e-0000-0000-0000-00000000000e', 'main_idea', 'What is the main idea?',
   '[{"key":"1","text":"Evolution always invents new tools."},{"key":"2","text":"Animals often survive by mimicking dangerous or harmless things."},{"key":"3","text":"Birds enjoy being stung."},{"key":"4","text":"Stick insects are slow."}]',
   '2', '본문 결론: 모방이 진화 전략이다.', 'mid', 10, null),
  ('b000000e-0000-0000-0000-00000000000e', 'blank', 'Fill in the blank: A stick insect looks like a ____.',
   '[{"key":"1","text":"flower"},{"key":"2","text":"twig"},{"key":"3","text":"bird"},{"key":"4","text":"mountain"}]',
   '2', 'looks like a twig.', 'mid', 10, null),
  ('b000000e-0000-0000-0000-00000000000e', 'vocabulary', 'In the passage, "disguise" most nearly means:',
   '[{"key":"1","text":"a thing that hides an identity"},{"key":"2","text":"a loud sound"},{"key":"3","text":"a small wound"},{"key":"4","text":"a friendly greeting"}]',
   '1', 'completes the disguise → 변장.', 'mid', 10, null),

  ('b000000f-0000-0000-0000-00000000000f', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Mixed-use streets save time and make neighborhoods livelier."},{"key":"2","text":"Cars must be separated from people."},{"key":"3","text":"Zoning was always a good idea."},{"key":"4","text":"Apartments should never be near shops."}]',
   '1', '본문 결론: 시간 절약 + 안전 + 활기.', 'mid', 11, null),
  ('b000000f-0000-0000-0000-00000000000f', 'blank', 'Fill in the blank: A mixed-use street puts shops on the ground floor, offices above, and ____ on top.',
   '[{"key":"1","text":"farms"},{"key":"2","text":"apartments"},{"key":"3","text":"airports"},{"key":"4","text":"forests"}]',
   '2', 'apartments on top.', 'mid', 11, null),
  ('b000000f-0000-0000-0000-00000000000f', 'vocabulary', 'In the passage, "lively" most nearly means:',
   '[{"key":"1","text":"full of activity and energy"},{"key":"2","text":"silent and empty"},{"key":"3","text":"dark and cold"},{"key":"4","text":"very expensive"}]',
   '1', 'lively → 활기찬.', 'mid', 11, null),

  ('b0000010-0000-0000-0000-000000000010', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Music styles never share anything across cultures."},{"key":"2","text":"Despite huge variation, some musical patterns are recognized as sad almost everywhere."},{"key":"3","text":"Lyrics decide whether music sounds sad."},{"key":"4","text":"Researchers cannot study music across cultures."}]',
   '2', '본문 결론: a small core seems to be shared.', 'mid', 10, null),
  ('b0000010-0000-0000-0000-000000000010', 'blank', 'Fill in the blank: Slow tempos resemble a sleeping ____.',
   '[{"key":"1","text":"city"},{"key":"2","text":"heartbeat"},{"key":"3","text":"river"},{"key":"4","text":"engine"}]',
   '2', 'sleeping heartbeat.', 'mid', 10, null),
  ('b0000010-0000-0000-0000-000000000010', 'vocabulary', 'In the passage, "echo" most nearly means:',
   '[{"key":"1","text":"to reflect or mirror"},{"key":"2","text":"to ignore"},{"key":"3","text":"to delete"},{"key":"4","text":"to invent"}]',
   '1', 'echo the sound → 비슷하게 따라간다.', 'mid', 10, null),

  ('b0000011-0000-0000-0000-000000000011', 'main_idea', 'What is the main idea?',
   '[{"key":"1","text":"Trade languages are temporary and useless."},{"key":"2","text":"Shared simplified languages emerged from practical need and sometimes became native tongues."},{"key":"3","text":"Greek is the only useful trade language."},{"key":"4","text":"All trade languages have complex grammar."}]',
   '2', '본문 전체 흐름 + 마지막 단락.', 'mid', 11, null),
  ('b0000011-0000-0000-0000-000000000011', 'blank', 'Fill in the blank: A trade language is built for usefulness, not for ____.',
   '[{"key":"1","text":"poetry"},{"key":"2","text":"war"},{"key":"3","text":"breakfast"},{"key":"4","text":"sleep"}]',
   '1', 'not for poetry.', 'mid', 11, null),
  ('b0000011-0000-0000-0000-000000000011', 'vocabulary', 'In the passage, "emerge" most nearly means:',
   '[{"key":"1","text":"to come into existence"},{"key":"2","text":"to disappear"},{"key":"3","text":"to fight"},{"key":"4","text":"to delete"}]',
   '1', 'emerged from the mix → 등장하다.', 'mid', 11, null),

  ('b0000012-0000-0000-0000-000000000012', 'main_idea', 'What is the main idea?',
   '[{"key":"1","text":"Children always make better decisions than adults."},{"key":"2","text":"People tend to prefer immediate rewards over larger future ones, but awareness helps."},{"key":"3","text":"Saving money is impossible."},{"key":"4","text":"Exercise is harmful."}]',
   '2', '본문 핵심: 현재 편향과 그 인식.', 'mid', 11, null),
  ('b0000012-0000-0000-0000-000000000012', 'blank', 'Fill in the blank: The mind treats future selves like ____.',
   '[{"key":"1","text":"family"},{"key":"2","text":"strangers"},{"key":"3","text":"teachers"},{"key":"4","text":"twins"}]',
   '2', 'like strangers.', 'mid', 11, null),
  ('b0000012-0000-0000-0000-000000000012', 'vocabulary', 'In the passage, "borrow" most nearly means:',
   '[{"key":"1","text":"to take with the intention of returning"},{"key":"2","text":"to throw away"},{"key":"3","text":"to copy a song"},{"key":"4","text":"to grow tall"}]',
   '1', 'borrow tomorrow''s money → 빌리다.', 'mid', 11, null),

  ('b0000013-0000-0000-0000-000000000013', 'main_idea', 'What is the main idea?',
   '[{"key":"1","text":"Individuals acting only for themselves can produce worse outcomes for everyone."},{"key":"2","text":"Betraying is always the wrong choice."},{"key":"3","text":"Prisoners always cooperate."},{"key":"4","text":"Group projects have no relation to economics."}]',
   '1', '본문 결론: 협력 부재의 함정.', 'mid', 11, null),
  ('b0000013-0000-0000-0000-000000000013', 'blank', 'Fill in the blank: If both follow that logic, both ____.',
   '[{"key":"1","text":"win"},{"key":"2","text":"lose"},{"key":"3","text":"escape"},{"key":"4","text":"sing"}]',
   '2', 'both lose.', 'mid', 11, null),
  ('b0000013-0000-0000-0000-000000000013', 'vocabulary', 'In the passage, "betray" most nearly means:',
   '[{"key":"1","text":"to be loyal to"},{"key":"2","text":"to break trust with"},{"key":"3","text":"to remain silent forever"},{"key":"4","text":"to celebrate together"}]',
   '2', 'betray each other → 배신하다.', 'mid', 11, null),

  ('b0000014-0000-0000-0000-000000000014', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Most of the matter in the universe cannot be seen, yet it shapes everything visible."},{"key":"2","text":"Telescopes can detect dark matter directly."},{"key":"3","text":"Galaxies spin slowly."},{"key":"4","text":"Astronomers have already solved the dark matter problem."}]',
   '1', '본문 핵심: 보이지 않는 물질이 우주 대부분을 차지.', 'mid', 11, null),
  ('b0000014-0000-0000-0000-000000000014', 'blank', 'Fill in the blank: About eighty-five percent of all matter in the universe is thought to be ____.',
   '[{"key":"1","text":"dark"},{"key":"2","text":"liquid"},{"key":"3","text":"musical"},{"key":"4","text":"frozen"}]',
   '1', 'thought to be dark.', 'mid', 11, null),
  ('b0000014-0000-0000-0000-000000000014', 'vocabulary', 'In the passage, "balance" most nearly means:',
   '[{"key":"1","text":"to match up so the totals are equal"},{"key":"2","text":"to weigh heavily"},{"key":"3","text":"to break apart"},{"key":"4","text":"to spin in a circle"}]',
